"""
FinCoach — embedded logo asset.

The logo is embedded directly as base64 (same trick already used for the
Life Simulation's character sprites) instead of being loaded from
assets/logo.png at runtime. That means it always renders — even if the
app is run from a different machine/folder where that file doesn't
happen to exist — instead of silently falling back to a plain emoji icon.

Source image was resized to 500x500 (from the original 2000x2000) purely
to keep this file a reasonable size; that's plenty of resolution for a
logo shown at 120-260px in the UI.
"""
import base64

LOGO_B64 = ""

LOGO_BYTES = base64.b64decode(LOGO_B64)